package com.bookstore.service;
import com.bookstore.entity.*; import com.bookstore.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class UserService { private final UserRepository repo; private final PasswordEncoder encoder; public UserService(UserRepository r,PasswordEncoder e){repo=r;encoder=e;} public User register(String u,String p,String e){if(repo.findByUsername(u).isPresent()) throw new IllegalArgumentException("Username already exists"); User x=new User(u,encoder.encode(p),e,Role.USER); return repo.save(x);} public User find(String u){return repo.findByUsername(u).orElseThrow();} public long count(){return repo.count();} public java.util.List<User> all(){return repo.findAll();} public void setRole(Long id,Role role){User u=repo.findById(id).orElseThrow();u.setRole(role);repo.save(u);} }
